* { box-sizing: border-box; }
body { margin:0; font-family: "Segoe UI", system-ui, -apple-system, sans-serif; font-size:13px; color:#212529; background:#f5f6f8; }
.xaf { display:flex; height:100vh; overflow:hidden; }

/* --- lewa nawigacja XAF --- */
.nav { width:230px; background:#2b3a4a; color:#c9d4de; flex-shrink:0; display:flex; flex-direction:column; }
.nav .brand { padding:14px 16px; font-weight:600; color:#fff; font-size:14px; border-bottom:1px solid #3b4c5e; display:flex; align-items:center; gap:8px; }
.nav .brand .logo { width:22px;height:22px;border-radius:4px;background:#4a9eff; display:inline-block; }
.nav .grp { padding:10px 16px 4px; font-size:11px; text-transform:uppercase; letter-spacing:.4px; color:#7d8fa1; }
.nav a { display:block; padding:7px 16px 7px 28px; color:#c9d4de; text-decoration:none; cursor:pointer; }
.nav a:hover { background:#35485c; color:#fff; }
.nav a.on { background:#0d6efd; color:#fff; font-weight:500; }

/* --- obszar roboczy --- */
.main { flex:1; display:flex; flex-direction:column; overflow:hidden; }
.top { background:#fff; border-bottom:1px solid #dee2e6; padding:10px 18px; display:flex; align-items:center; gap:12px; }
.top h1 { font-size:16px; margin:0; font-weight:600; }
.top .spacer { flex:1; }
.user { color:#6c757d; font-size:12px; }
.bar { background:#fff; border-bottom:1px solid #dee2e6; padding:7px 18px; display:flex; gap:6px; align-items:center; flex-wrap:wrap; }
.btn { border:1px solid #ced4da; background:#fff; border-radius:4px; padding:5px 11px; font-size:12.5px; cursor:pointer; color:#212529; display:inline-flex; align-items:center; gap:5px; }
.btn:hover { background:#f1f3f5; }
.btn.pri { background:#0d6efd; border-color:#0d6efd; color:#fff; }
.btn.pri:hover { background:#0b5ed7; }
.btn.warn { border-color:#f0a500; color:#8a6100; }
.body { flex:1; overflow:auto; padding:16px 18px; }

/* --- grid --- */
table.grid { width:100%; border-collapse:collapse; background:#fff; border:1px solid #dee2e6; }
table.grid th { text-align:left; font-weight:600; font-size:12px; padding:8px 10px; background:#f8f9fa; border-bottom:2px solid #dee2e6; white-space:nowrap; }
table.grid td { padding:7px 10px; border-bottom:1px solid #eceef0; vertical-align:middle; }
table.grid tr.filter td { background:#fbfcfd; padding:5px 8px; }
table.grid tr.filter input { width:100%; border:1px solid #ced4da; border-radius:3px; padding:3px 6px; font-size:12px; }
table.grid tbody tr:hover { background:#f4f8ff; }
code { font-family: "Cascadia Mono", Consolas, monospace; font-size:12px; background:#f1f3f5; padding:1px 5px; border-radius:3px; }

/* wyróżnienie wierszy — odpowiednik statycznego [Appearance] */
tr.zla td { background:#fdeaea; color:#842029; }
tr.zla:hover td { background:#fbdcdc; }
tr.ostrz td { background:#fff6e0; color:#7a5b00; }
tr.wyl td { color:#9aa2ab; font-style:italic; }

/* --- odznaki --- */
.b { display:inline-block; padding:2px 8px; border-radius:10px; font-size:11.5px; font-weight:600; white-space:nowrap; }
.b.ok { background:#d1e7dd; color:#0a3622; }
.b.zla { background:#f8d7da; color:#842029; }
.b.ostrz { background:#ffe8b8; color:#7a5b00; }
.b.n { background:#e9ecef; color:#495057; font-weight:500; }
.prob { display:inline-block; width:13px; height:13px; border-radius:3px; vertical-align:-2px; margin-right:6px; border:1px solid rgba(0,0,0,.15); }

/* --- karta / detailview --- */
.karta { background:#fff; border:1px solid #dee2e6; border-radius:4px; }
.tabs { display:flex; border-bottom:1px solid #dee2e6; background:#f8f9fa; }
.tabs div { padding:9px 18px; cursor:pointer; font-size:13px; color:#495057; border-bottom:2px solid transparent; }
.tabs div.on { background:#fff; color:#0d6efd; border-bottom-color:#0d6efd; font-weight:600; }
.grupa { padding:14px 18px; }
.grupa > h3 { font-size:12px; text-transform:uppercase; letter-spacing:.4px; color:#6c757d; margin:0 0 12px; font-weight:600; }
.pola { display:grid; grid-template-columns:190px 1fr; gap:11px 14px; align-items:center; max-width:820px; }
.pola label { color:#495057; text-align:right; }
.pola .v { border:1px solid #ced4da; border-radius:3px; padding:6px 9px; background:#fff; }
.pola .v.ro { background:#f8f9fa; color:#6c757d; }
.pola .peln { grid-column:1/-1; }
.hint { color:#6c757d; font-size:11.5px; margin-top:4px; }
.chk { display:flex; flex-wrap:wrap; gap:7px 18px; border:1px solid #ced4da; border-radius:3px; padding:9px; background:#fff; }
.chk label { text-align:left; color:#212529; display:flex; align-items:center; gap:5px; }

/* --- panel diagnozy --- */
.diag { margin:0 18px 16px; border:1px solid #f1aeb5; border-left:4px solid #dc3545; background:#fdf2f3; border-radius:4px; padding:12px 14px; }
.diag h4 { margin:0 0 6px; font-size:13px; color:#842029; }
.diag p { margin:0 0 4px; color:#5c2126; }
.diag .fix { margin-top:9px; }

/* --- czat --- */
.czat { max-width:760px; margin:0 auto; }
.msg { display:flex; gap:10px; margin-bottom:14px; }
.msg .av { width:30px;height:30px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:600;color:#fff; }
.msg.u .av { background:#6c757d; }
.msg.a .av { background:#0d6efd; }
.msg .tresc { background:#fff; border:1px solid #dee2e6; border-radius:8px; padding:10px 13px; flex:1; }
.msg.u .tresc { background:#eef4ff; border-color:#cfe0ff; }
.msg .tresc p { margin:0 0 8px; } .msg .tresc p:last-child { margin:0; }
.msg .kto { font-size:11px; color:#6c757d; margin-bottom:3px; }
.narz { border:1px dashed #b8c4d0; border-radius:5px; background:#f8fafc; padding:8px 11px; margin:9px 0; font-family:"Cascadia Mono",Consolas,monospace; font-size:11.5px; color:#33475b; }
.narz .n { color:#0d6efd; font-weight:600; }
.narz.zle { border-color:#f1aeb5; background:#fdf2f3; color:#842029; }
.pisz { display:flex; gap:8px; margin-top:16px; }
.pisz input { flex:1; border:1px solid #ced4da; border-radius:20px; padding:9px 15px; font-size:13px; }
.mikro { width:36px;height:36px;border-radius:50%;border:1px solid #ced4da;background:#fff;cursor:pointer;font-size:15px; }

.podpis { color:#6c757d; font-size:11.5px; margin-top:10px; }

